function denied(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

async function deniedAsync(operation) {
  try {
    await operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function websocketAttempt(url) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      const socket = new WebSocket(url);
      socket.addEventListener("open", () => {
        socket.close();
        finish("ALLOWED");
      }, { once: true });
      socket.addEventListener("error", () => finish("DENIED"), { once: true });
      setTimeout(() => finish("DENIED"), 1000);
    } catch {
      finish("DENIED");
    }
  });
}

function nodeSocketAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    socket.once("error", () => finish("DENIED"));
    socket.write("GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n", (error) =>
      finish(error ? "DENIED" : "ALLOWED")
    );
    setTimeout(() => finish("DENIED"), 1000);
  });
}

function nodeSocketReadAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      socket.once("data", () => finish("ALLOWED"));
      socket.once("error", () => finish("DENIED"));
      socket.resume();
    } catch {
      finish("DENIED");
    }
    setTimeout(() => finish("DENIED"), 1000);
  });
}

function websocketReadAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    socket.addEventListener("message", () => finish("ALLOWED"), { once: true });
    socket.addEventListener("error", () => finish("DENIED"), { once: true });
    socket.addEventListener("close", () => finish("DENIED"), { once: true });
    setTimeout(() => finish("DENIED"), 1000);
  });
}

async function probeEndpointPassage(resources) {
  return {
    directFetch: await deniedAsync(() => fetch(resources.httpUrl)),
    directDnsFetch: await deniedAsync(() => fetch(resources.dnsHttpUrl)),
    directWebSocket: await websocketAttempt(resources.wsUrl),
    directDnsWebSocket: await websocketAttempt(resources.dnsWsUrl),
    passedDenoConn: await deniedAsync(() => resources.denoConn.write(
      new TextEncoder().encode("GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n"),
    )),
    passedDenoConnRead: await deniedAsync(() => resources.readDenoConn.read(
      new Uint8Array(4096),
    )),
    passedNodeSocket: await nodeSocketAttempt(resources.nodeSocket),
    passedNodeSocketRead: await nodeSocketReadAttempt(resources.readNodeSocket),
    passedResponse: await deniedAsync(() => resources.rootResponse.text()),
    passedDnsResponse: await deniedAsync(() => resources.rootDnsResponse.text()),
    passedWebSocket: denied(() => resources.rootWebSocket.send(
      JSON.stringify({ id: 1, method: "Runtime.enable" }),
    )),
    passedDnsWebSocket: denied(() => resources.rootDnsWebSocket.send(
      JSON.stringify({ id: 2, method: "Runtime.enable" }),
    )),
    passedWebSocketRead: await websocketReadAttempt(resources.readWebSocket),
  };
}

probeEndpointPassage.afterClose = (response) =>
  deniedAsync(() => response.text());

module.exports = probeEndpointPassage;
